CREATE OR REPLACE FUNCTION public.correct_asset_placement_dates(p_assignment_id uuid,p_start_at timestamptz,p_end_at timestamptz,p_reason text,p_expected_updated_at timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.asset_assignments%ROWTYPE; BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Managers only'; END IF; SELECT * INTO a FROM public.asset_assignments WHERE id=p_assignment_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Placement not found'; END IF; IF a.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'Placement changed; reload before editing'; END IF; IF nullif(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'A correction reason is required'; END IF; IF p_start_at IS NULL OR (p_end_at IS NOT NULL AND p_end_at<=p_start_at) THEN RAISE EXCEPTION 'Departure must follow arrival'; END IF; IF a.status<>'active' AND p_end_at IS NULL THEN RAISE EXCEPTION 'Ended placements must keep a departure date'; END IF; PERFORM 1 FROM public.assets WHERE id=a.asset_id FOR UPDATE; PERFORM set_config('app.billing_date_correction',a.id::text,true); UPDATE public.asset_assignments SET start_at=p_start_at,end_at=p_end_at WHERE id=a.id; PERFORM set_config('app.billing_date_correction','',true); INSERT INTO public.audit_logs(user_id,user_email,action_type,resource_type,resource_id,changes_before,changes_after,metadata) VALUES(auth.uid(),coalesce((SELECT email FROM public.profiles WHERE id=auth.uid()),auth.jwt()->>'email','authenticated-user'),'update','asset_assignment',a.id,jsonb_build_object('start_at',a.start_at,'end_at',a.end_at),jsonb_build_object('start_at',p_start_at,'end_at',p_end_at),jsonb_build_object('reason',trim(p_reason),'operation','placement_date_correction','billing_only',true)); END $$;
CREATE OR REPLACE FUNCTION public.track_asset_custody() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE at_time timestamptz:=now(); BEGIN IF TG_OP='UPDATE' AND current_setting('app.billing_date_correction',true)=NEW.id::text AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) AND NEW.assigned_to_personnel_id IS NOT DISTINCT FROM OLD.assigned_to_personnel_id AND NEW.status=OLD.status AND NEW.unassigned_at IS NOT DISTINCT FROM OLD.unassigned_at THEN RETURN NEW; END IF; IF TG_OP='UPDATE' AND NEW.assigned_to_personnel_id IS NOT DISTINCT FROM OLD.assigned_to_personnel_id AND NEW.end_at IS NOT DISTINCT FROM OLD.end_at AND NEW.status=OLD.status AND NEW.unassigned_at IS NOT DISTINCT FROM OLD.unassigned_at THEN RETURN NEW; END IF; IF NEW.assigned_to_personnel_id IS NOT NULL AND NEW.status='active' AND NEW.end_at IS NULL AND NEW.unassigned_at IS NULL AND NEW.location_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.location_assignments l WHERE l.location_id=NEW.location_id AND l.personnel_id=NEW.assigned_to_personnel_id AND l.status='active' AND (l.assigned_at IS NULL OR l.assigned_at<=now()) AND (l.unassigned_at IS NULL OR l.unassigned_at>now())) OR EXISTS(SELECT 1 FROM public.personnel_current_status s WHERE s.personnel_id=NEW.assigned_to_personnel_id AND s.project_id=NEW.project_id AND s.status='demobilized') THEN RAISE EXCEPTION 'Responsible person must be actively assigned at this location'; END IF; END IF; IF TG_OP='UPDATE' THEN UPDATE public.asset_custody_history SET ended_at=COALESCE(NEW.end_at,NEW.unassigned_at,at_time) WHERE assignment_id=OLD.id AND ended_at IS NULL; END IF; IF NEW.assigned_to_personnel_id IS NOT NULL AND NEW.status='active' AND NEW.end_at IS NULL AND NEW.unassigned_at IS NULL THEN INSERT INTO public.asset_custody_history(assignment_id,personnel_id,started_at,changed_by) VALUES(NEW.id,NEW.assigned_to_personnel_id,CASE WHEN TG_OP='INSERT' THEN NEW.start_at ELSE at_time END,auth.uid()); END IF; RETURN NEW; END $$;